CREATE TABLE users(id BIGSERIAL PRIMARY KEY,email VARCHAR(255) NOT NULL,password_hash VARCHAR(255) NOT NULL,name VARCHAR(120) NOT NULL,role VARCHAR(20) NOT NULL CHECK(role IN('ADMIN','DISPATCHER','COURIER','CUSTOMER')),is_active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE UNIQUE INDEX users_email_unique_ci ON users(LOWER(email));
CREATE TABLE sessions(id UUID PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires_at TIMESTAMPTZ NOT NULL,revoked_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE shipments(id BIGSERIAL PRIMARY KEY,tracking_number VARCHAR(24) NOT NULL UNIQUE,sender_name VARCHAR(120) NOT NULL,sender_phone VARCHAR(40) NOT NULL DEFAULT '',recipient_name VARCHAR(120) NOT NULL,recipient_phone VARCHAR(40) NOT NULL DEFAULT '',origin VARCHAR(200) NOT NULL,destination VARCHAR(200) NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'CREATED' CHECK(status IN('CREATED','PICKED_UP','IN_TRANSIT','OUT_FOR_DELIVERY','DELIVERED','CANCELLED')),customer_id BIGINT NOT NULL REFERENCES users(id),assigned_courier_id BIGINT REFERENCES users(id),expected_delivery DATE,delivered_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX shipments_customer_idx ON shipments(customer_id);CREATE INDEX shipments_courier_idx ON shipments(assigned_courier_id);CREATE INDEX shipments_status_idx ON shipments(status,updated_at DESC);
CREATE TABLE tracking_events(id BIGSERIAL PRIMARY KEY,shipment_id BIGINT NOT NULL REFERENCES shipments(id) ON DELETE CASCADE,status VARCHAR(30) NOT NULL CHECK(status IN('CREATED','PICKED_UP','IN_TRANSIT','OUT_FOR_DELIVERY','DELIVERED','CANCELLED')),location VARCHAR(200) NOT NULL DEFAULT '',notes VARCHAR(1000) NOT NULL DEFAULT '',recorded_by BIGINT NOT NULL REFERENCES users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX tracking_events_shipment_idx ON tracking_events(shipment_id,created_at);
